{
  "schema_version": 1,
  "observations": [
    {
      "key": "obs_sort_definition",
      "facet": "term",
      "statement": "Sort is defined as arranging items in a predetermined order.",
      "start_line": 5,
      "end_line": 5
    },
    {
      "key": "obs_sort_formal",
      "facet": "property",
      "statement": "A sort operation transforms an initial array S of N items into a final array S' such that S' is a permutation of S and S'[i] <= S'[i+1] for 0 < i < N.",
      "start_line": 13,
      "end_line": 22
    },
    {
      "key": "obs_sort_factors",
      "facet": "precondition",
      "statement": "The choice of sorting algorithm depends on factors including the number of items relative to working memory, knowledge of the orderliness of items or range of keys, and the cost of comparing keys vs. moving items.",
      "start_line": 5,
      "end_line": 7
    },
    {
      "key": "obs_sort_properties",
      "facet": "property",
      "statement": "Most sorting algorithms can be implemented as in-place sorts, and many can be implemented to be stable.",
      "start_line": 8,
      "end_line": 11
    },
    {
      "key": "obs_sort_stability_mechanism",
      "facet": "mechanism",
      "statement": "Any sorting algorithm can be made stable by appending the original position to the key, allowing positions to break ties when keys are otherwise equal.",
      "start_line": 91,
      "end_line": 93
    },
    {
      "key": "obs_sort_etymology",
      "facet": "term",
      "statement": "The term 'sort' in Computer Science originated from early automated ordering procedures using punched card machines that classified cards by holes to implement radix sort.",
      "start_line": 96,
      "end_line": 98
    },
    {
      "key": "obs_sort_knuth_note",
      "facet": "reference",
      "statement": "Knuth notes that the sort operation might be called 'order'.",
      "start_line": 94,
      "end_line": 95
    },
    {
      "key": "obs_sort_list",
      "facet": "relation",
      "statement": "Specific sorting algorithms include quicksort, heapsort, Shell sort, comb sort, radix sort, bucket sort, insertion sort, selection sort, merge sort, counting sort, histogram sort, strand sort, q sort, J sort, shuffle sort, American flag sort, gnome sort, bubble sort, bidirectional bubble sort, treesort, adaptive heap sort, multikey Quicksort, and topological sort.",
      "start_line": 29,
      "end_line": 74
    },
    {
      "key": "obs_sort_related",
      "facet": "relation",
      "statement": "Related concepts include external sort, internal sort, comparison sort, distribution sort, easy split/hard merge, hard split/easy merge, and derangement.",
      "start_line": 76,
      "end_line": 89
    }
  ],
  "claims": [],
  "questions": []
}
